/**
 * Unit tests for FastDateFormat.getDateTimeInstance
 */
public class FastDateFormat_getDateTimeInstance_TriageGen0Test {

    @Test
    public void testGetDateTimeInstance_WithAllParameters() {
        int dateStyle = java.text.DateFormat.MEDIUM;
        int timeStyle = java.text.DateFormat.SHORT;
        TimeZone timeZone = TimeZone.getTimeZone("GMT");
        Locale locale = Locale.US;

        FastDateFormat format = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);

        assertNotNull("Format should not be null", format);
        assertEquals("TimeZone should match", timeZone, format.getTimeZone());
        assertEquals("Locale should match", locale, format.getLocale());
    }








}

