public class FastDateFormat_getDateTimeInstance_TriageGen0Test {







    @Test
    public void testGetDateTimeInstance_CacheConsistency() {
        int dateStyle = java.text.DateFormat.SHORT;
        int timeStyle = java.text.DateFormat.SHORT;
        TimeZone timeZone = TimeZone.getTimeZone("UTC");
        Locale locale = Locale.UK;

        FastDateFormat format1 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);
        FastDateFormat format2 = FastDateFormat.getDateTimeInstance(dateStyle, timeStyle, timeZone, locale);

        // Since it uses a cache, the instances should be the same (identity check)
        assertSame("Should return same instance from cache", format1, format2);
    }


}

